WITH src AS (SELECT *, CONCAT_WS(',', supplier_name, city) AS supplier_name_city_key FROM suppliers WHERE NOT (UPPER(TRIM(supplier_name)) = 'PACIFIC WHOLESALE' OR city = 'Bangkok')), suppliers_stats AS (SELECT CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(DISTINCT rating) AS unique_countrys FROM src GROUP BY CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END) SELECT rating_bucket, unique_countrys FROM suppliers_stats WHERE unique_countrys >= 6 ORDER BY rating_bucket, unique_countrys DESC LIMIT 1;
